{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 청년 기본 조례상 청년 비정규직 고용차별 개선 조치",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "시장은 청년 비정규직에 대한 고용차별을 개선하고 일자리의 질을 향상시키기 위한 방안을 강구하여야 한다. 또한 「근로기준법」에서 정한 기준에 미달하는 노동조건에 있는 청년노동자의 권리 구제를 위해 노력하여야 한다.",
          "b_ids": "청년:제12조제5항"
        }
      ],
      "e_status": "ANSWERED"
    },
    {
      "a_request": "R2",
      "b_asked": "서울특별시 청년 기본 조례상 취약계층 청년의 노동시장 진입 대책",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "시장은 취약계층 청년의 자립과 노동시장 진입을 위한 대책을 마련하여야 한다. 여기서 취약계층 청년이란 고용·교육·복지 등의 분야에서 어려움을 겪는 청년을 말한다.",
          "b_ids": "청년:제12조제6항, 청년:제3조제7호"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
